<?php
 $serviceClass = 'bgu_common_main'; class bgu_common_main extends common_main { private $maxId = 0; public function readNavigatorItems ($params) { $appConfig = getSessionValue('appConfig'); if (empty($appConfig['reportsPath'])) { throw new \Exception("Отсутствует настройка пути к репозитарию отчетов"); } $path = $appConfig['reportsPath']; if (!is_dir($path)) { throw new \Exception("Неверный путь к репозитарию отчетов"); } $root = new \stdClass(); $this->doDir($path, $root); return $root; } private function doDir ($dir, $parent) { $parent->children = []; for ($pass = 1; $pass <= 2; ++$pass) { $handle = opendir($dir); while ($file = readdir($handle)) { if (($file != ".") && ($file != "..")) { $fullName = "$dir/$file"; if ($pass === 1 && is_dir($fullName)) { $parent->children[] = $newDir = (object)[ 'id' => ++$this->maxId, 'name' => $file, ]; $this->doDir($fullName, $newDir); } else if ($pass === 2 && is_file($fullName) && substr($file, -4) === '.mrt') { $name = substr($file, 0, safe_strlen($file) - 4); $parent->children[] = (object)[ 'id' => ++$this->maxId, 'name' => $name, 'leaf' => true, 'widget' => 'reportbuilder-viewer', 'iconCls' => 'x-fa fa-file-text-o', 'params' => (object)[ 'report' => $fullName ] ]; } } } closedir($handle); } } } 